-- including non-active concepts retained to measure ontology gaps; qrels are not model output.

BEGIN;
SET CONSTRAINTS ALL DEFERRED;

DO $preflight$
DECLARE checked_count BIGINT;
BEGIN
  IF current_setting('server_version_num')::INTEGER < 170000 THEN
    RAISE EXCEPTION 'Round 2B evaluation seed requires PostgreSQL 17';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_trgm') THEN
    RAISE EXCEPTION 'Round 2B evaluation seed requires pg_trgm';
  END IF;
  SELECT count(*) INTO checked_count
  FROM corpus.corpus_snapshot AS snapshot
  JOIN corpus.normalization_pipeline AS pipeline
    ON pipeline.normalization_pipeline_id = snapshot.normalization_pipeline_id
  JOIN corpus.normalization_derivation_run AS derivation
    ON derivation.corpus_snapshot_id = snapshot.corpus_snapshot_id
   AND derivation.normalization_pipeline_id = pipeline.normalization_pipeline_id
  WHERE snapshot.corpus_snapshot_key = 'corpus_snapshot.firstbloom_a6cb002_pilot_v1' AND snapshot.frozen_at IS NOT NULL
    AND pipeline.normalization_pipeline_key = 'normalization.en_v1' AND pipeline.frozen_at IS NOT NULL
    AND derivation.normalization_derivation_run_key = 'normalization_run.firstbloom_a6cb002_pilot_v1.en_v1' AND derivation.frozen_at IS NOT NULL;
  IF checked_count <> 1 THEN RAISE EXCEPTION 'Frozen snapshot/pipeline/derivation contract not found exactly once'; END IF;
