DO $seed_closure$
DECLARE checked_count BIGINT;
BEGIN
  SELECT count(*) INTO checked_count FROM _r2b_eval_case_seed AS seed JOIN kb.lexical_expression AS expression ON encode(sha256(convert_to(expression.expression_key, 'UTF8')), 'hex') = seed.expression_key_sha256 JOIN corpus.observation_expression AS occurrence ON encode(sha256(convert_to(occurrence.observation_expression_key, 'UTF8')), 'hex') = seed.observation_expression_key_sha256 AND occurrence.expression_id = expression.expression_id;
  IF checked_count <> 300 THEN RAISE EXCEPTION 'Hash-only audit case identities do not resolve exactly'; END IF;
  IF EXISTS (SELECT 1 FROM _r2b_eval_candidate_seed AS seed LEFT JOIN kb.concept AS concept ON concept.concept_key = seed.concept_key AND concept.lifecycle_status_code = 'active' WHERE concept.concept_id IS NULL) THEN RAISE EXCEPTION 'Candidate concept is absent or inactive'; END IF;
  IF EXISTS (SELECT 1 FROM _r2b_eval_judgment_seed AS seed LEFT JOIN kb.concept AS concept ON concept.concept_key = seed.concept_key WHERE concept.concept_id IS NULL) THEN RAISE EXCEPTION 'Judged concept is absent'; END IF;
  IF EXISTS (SELECT 1 FROM _r2b_eval_candidate_seed AS seed WHERE seed.retrieval_tier_code IN ('A','B','C') AND (SELECT count(*) FROM kb.lexical_expression AS expression WHERE encode(sha256(convert_to(expression.expression_key, 'UTF8')), 'hex') = seed.matched_expression_key_sha256) <> 1) THEN RAISE EXCEPTION 'Direct matched expression hash does not resolve exactly once'; END IF;
  IF EXISTS (SELECT 1 FROM _r2b_eval_candidate_seed AS graph WHERE graph.retrieval_tier_code = 'D' AND NOT EXISTS (SELECT 1 FROM _r2b_eval_candidate_seed AS seed WHERE seed.audit_case_key = graph.audit_case_key AND seed.retrieval_baseline_code = graph.retrieval_baseline_code AND seed.concept_key = graph.seed_concept_key AND seed.retrieval_tier_code IN ('A','B','C'))) THEN RAISE EXCEPTION 'Graph candidate lacks an in-scope direct seed'; END IF;
END;
$seed_closure$;

