INSERT INTO audit.retrieval_audit_case (retrieval_audit_case_key, retrieval_audit_set_id, expression_id, representative_observation_expression_id, audit_split_code, case_ordinal, notes) SELECT seed.audit_case_key, audit_set.retrieval_audit_set_id, expression.expression_id, occurrence.observation_expression_id, seed.audit_split_code, seed.case_ordinal, 'Frozen selection SHA-256: ' || seed.selection_sha256 FROM _r2b_eval_case_seed AS seed JOIN audit.retrieval_audit_set AS audit_set ON audit_set.retrieval_audit_set_key = 'audit_set.round2b.firstbloom_pilot_v1' JOIN kb.lexical_expression AS expression ON encode(sha256(convert_to(expression.expression_key, 'UTF8')), 'hex') = seed.expression_key_sha256 JOIN corpus.observation_expression AS occurrence ON encode(sha256(convert_to(occurrence.observation_expression_key, 'UTF8')), 'hex') = seed.observation_expression_key_sha256 AND occurrence.expression_id = expression.expression_id ORDER BY seed.case_ordinal;
INSERT INTO audit.retrieval_audit_case_stratum (retrieval_audit_case_id, retrieval_audit_stratum_code) SELECT audit_case.retrieval_audit_case_id, seed.retrieval_audit_stratum_code FROM _r2b_eval_stratum_seed AS seed JOIN audit.retrieval_audit_case AS audit_case ON audit_case.retrieval_audit_case_key = seed.audit_case_key ORDER BY audit_case.retrieval_audit_case_id, seed.retrieval_audit_stratum_code;

INSERT INTO audit.reviewer (reviewer_key, display_name, affiliation) VALUES ('reviewer.round2b.private_sha256_945895fd09c427dac95c9e27c32a4feaff5e4ad7f498cb66c19cd68ee1a75be4', 'Round 2B independent reviewer 1 (pseudonymous)', NULL);
INSERT INTO audit.reviewer (reviewer_key, display_name, affiliation) VALUES ('reviewer.round2b.private_sha256_683bcb200488eb35274743ee3ff68205f214b7572dece77552406385b5a97af6', 'Round 2B independent reviewer 2 (pseudonymous)', NULL);
INSERT INTO audit.reviewer (reviewer_key, display_name, affiliation) VALUES ('reviewer.round2b.private_sha256_aea2ae2464d31879037d89a56fdbe0c44529b3dfdfd0067890466635c24b571a', 'Round 2B adjudicator (pseudonymous)', NULL);
INSERT INTO audit.retrieval_case_review (retrieval_case_review_key, retrieval_audit_case_id, reviewer_id, audit_review_role_code, expects_unresolved, reviewed_at, notes) SELECT seed.retrieval_case_review_key, audit_case.retrieval_audit_case_id, reviewer.reviewer_id, seed.audit_review_role_code, seed.expects_unresolved, seed.reviewed_at, 'Private ledger SHA-256: ' || seed.private_ledger_sha256 || '; decision receipt SHA-256: ' || seed.decision_sha256 FROM _r2b_eval_review_seed AS seed JOIN audit.retrieval_audit_case AS audit_case ON audit_case.retrieval_audit_case_key = seed.audit_case_key JOIN audit.reviewer AS reviewer ON reviewer.reviewer_key = seed.reviewer_key ORDER BY audit_case.retrieval_audit_case_id, seed.audit_review_role_code, reviewer.reviewer_id;
INSERT INTO audit.retrieval_relevance_judgment (retrieval_relevance_judgment_key, retrieval_case_review_id, concept_id, relevance_grade_code, rationale) SELECT seed.retrieval_relevance_judgment_key, review.retrieval_case_review_id, concept.concept_id, seed.relevance_grade_code, 'Private rationale withheld; SHA-256=' || seed.private_rationale_sha256 FROM _r2b_eval_judgment_seed AS seed JOIN audit.retrieval_case_review AS review ON review.retrieval_case_review_key = seed.retrieval_case_review_key JOIN kb.concept AS concept ON concept.concept_key = seed.concept_key ORDER BY review.retrieval_case_review_id, concept.concept_id;

INSERT INTO ml.mapping_inference (mapping_inference_key, model_run_id, observation_expression_id, resolution_status_code, inferred_at, resolution_notes) SELECT seed.mapping_inference_key, run.model_run_id, audit_case.representative_observation_expression_id, seed.resolution_status_code, '2026-08-24T07:48:49Z'::TIMESTAMPTZ, CASE seed.resolution_status_code WHEN 'unresolved' THEN 'Explicit deterministic abstention: no candidate survived.' WHEN 'resolved' THEN 'Exactly one direct approved A/B candidate resolved the expression.' ELSE 'Reviewable ordinal candidates; no forced resolution.' END FROM _r2b_eval_inference_seed AS seed JOIN ml.model_run AS run ON run.model_run_key = seed.model_run_key JOIN audit.retrieval_audit_case AS audit_case ON audit_case.retrieval_audit_case_key = seed.audit_case_key ORDER BY run.model_run_id, audit_case.case_ordinal;
INSERT INTO ml.mapping_candidate (mapping_candidate_key, mapping_inference_id, concept_id, candidate_status_code, rank, rationale) SELECT 'mapping_candidate.round2b.sha256_' || encode(sha256(convert_to('round2b-evaluation-persistence-v1' || inference.mapping_inference_key || E'\x1f' || seed.concept_key, 'UTF8')), 'hex'), inference.mapping_inference_id, concept.concept_id, 'proposed', seed.candidate_rank, 'Deterministic ordinal retrieval candidate; signals are preserved separately without a weighted aggregate.' FROM _r2b_eval_candidate_seed AS seed JOIN _r2b_eval_inference_seed AS inference_seed ON inference_seed.audit_case_key = seed.audit_case_key AND inference_seed.retrieval_baseline_code = seed.retrieval_baseline_code JOIN ml.mapping_inference AS inference ON inference.mapping_inference_key = inference_seed.mapping_inference_key JOIN kb.concept AS concept ON concept.concept_key = seed.concept_key ORDER BY inference.mapping_inference_id, seed.candidate_rank;
INSERT INTO ml.deterministic_candidate_trace (mapping_candidate_id, retrieval_tier_code, matched_expression_id, seed_mapping_candidate_id, concept_relation_id, traversal_direction, graph_hop_count, raw_surface_exact, normalized_phrase_match) SELECT candidate.mapping_candidate_id, seed.retrieval_tier_code, expression.expression_id, NULL, NULL, NULL, 0, seed.raw_surface_exact, seed.normalized_phrase_match FROM _r2b_eval_candidate_seed AS seed JOIN _r2b_eval_inference_seed AS inference_seed ON inference_seed.audit_case_key = seed.audit_case_key AND inference_seed.retrieval_baseline_code = seed.retrieval_baseline_code JOIN ml.mapping_inference AS inference ON inference.mapping_inference_key = inference_seed.mapping_inference_key JOIN ml.mapping_candidate AS candidate ON candidate.mapping_inference_id = inference.mapping_inference_id JOIN kb.concept AS concept ON concept.concept_id = candidate.concept_id AND concept.concept_key = seed.concept_key JOIN kb.lexical_expression AS expression ON encode(sha256(convert_to(expression.expression_key, 'UTF8')), 'hex') = seed.matched_expression_key_sha256 WHERE seed.retrieval_tier_code IN ('A','B','C') ORDER BY candidate.mapping_candidate_id;
INSERT INTO ml.deterministic_candidate_trace (mapping_candidate_id, retrieval_tier_code, matched_expression_id, seed_mapping_candidate_id, concept_relation_id, traversal_direction, graph_hop_count, raw_surface_exact, normalized_phrase_match) SELECT candidate.mapping_candidate_id, 'D', NULL, seed_candidate.mapping_candidate_id, neighbour.concept_relation_id, seed.traversal_direction, 1, FALSE, FALSE FROM _r2b_eval_candidate_seed AS seed JOIN _r2b_eval_inference_seed AS inference_seed ON inference_seed.audit_case_key = seed.audit_case_key AND inference_seed.retrieval_baseline_code = seed.retrieval_baseline_code JOIN ml.mapping_inference AS inference ON inference.mapping_inference_key = inference_seed.mapping_inference_key JOIN ml.mapping_candidate AS candidate ON candidate.mapping_inference_id = inference.mapping_inference_id JOIN kb.concept AS concept ON concept.concept_id = candidate.concept_id AND concept.concept_key = seed.concept_key JOIN kb.concept AS seed_concept ON seed_concept.concept_key = seed.seed_concept_key JOIN ml.mapping_candidate AS seed_candidate ON seed_candidate.mapping_inference_id = inference.mapping_inference_id AND seed_candidate.concept_id = seed_concept.concept_id JOIN kb.v_concept_neighbours AS neighbour ON neighbour.concept_id = seed_concept.concept_id AND neighbour.neighbour_concept_id = concept.concept_id AND neighbour.relation_type_code = seed.relation_type_code AND neighbour.traversal_direction = seed.traversal_direction WHERE seed.retrieval_tier_code = 'D' ORDER BY candidate.mapping_candidate_id;
INSERT INTO ml.candidate_signal (candidate_signal_key, mapping_candidate_id, signal_domain_code, statistical_method_id, dataset_id, measurement_scale_id, signal_value, value_semantics, context) SELECT signal.candidate_signal_key, candidate.mapping_candidate_id, signal_type.signal_domain_code, method.statistical_method_id, snapshot.manifest_dataset_id, scale.measurement_scale_id, signal.signal_value, signal.value_semantics, signal.context FROM _r2b_eval_signal_seed AS signal JOIN _r2b_eval_inference_seed AS inference_seed ON inference_seed.audit_case_key = signal.audit_case_key AND inference_seed.retrieval_baseline_code = signal.retrieval_baseline_code JOIN ml.mapping_inference AS inference ON inference.mapping_inference_key = inference_seed.mapping_inference_key JOIN ml.mapping_candidate AS candidate ON candidate.mapping_inference_id = inference.mapping_inference_id JOIN kb.concept AS concept ON concept.concept_id = candidate.concept_id AND concept.concept_key = signal.concept_key JOIN ref.retrieval_signal AS signal_type ON signal_type.retrieval_signal_code = signal.retrieval_signal_code JOIN evidence.statistical_method AS method ON method.method_key = CASE signal.retrieval_signal_code WHEN 'pg_trgm_similarity' THEN 'statistical_method.round2b.pg_trgm_similarity' WHEN 'typed_graph_hop' THEN 'statistical_method.round2b.typed_graph_hop' ELSE 'statistical_method.round2b.deterministic_indicator' END JOIN evidence.measurement_scale AS scale ON scale.scale_key = CASE signal.retrieval_signal_code WHEN 'pg_trgm_similarity' THEN 'measurement_scale.round2b.unit_interval' WHEN 'typed_graph_hop' THEN 'measurement_scale.round2b.one_hop' ELSE 'measurement_scale.round2b.binary_indicator' END JOIN corpus.corpus_snapshot AS snapshot ON snapshot.corpus_snapshot_key = 'corpus_snapshot.firstbloom_a6cb002_pilot_v1' ORDER BY candidate.mapping_candidate_id, signal.signal_ordinal;
INSERT INTO ml.deterministic_candidate_signal (candidate_signal_id, mapping_candidate_id, retrieval_signal_code, signal_ordinal) SELECT candidate_signal.candidate_signal_id, candidate_signal.mapping_candidate_id, seed.retrieval_signal_code, seed.signal_ordinal FROM _r2b_eval_signal_seed AS seed JOIN ml.candidate_signal AS candidate_signal ON candidate_signal.candidate_signal_key = seed.candidate_signal_key ORDER BY candidate_signal.mapping_candidate_id, seed.signal_ordinal;

