UPDATE audit.retrieval_audit_set SET frozen_at = '2026-08-24T08:31:00Z'::TIMESTAMPTZ WHERE retrieval_audit_set_key = 'audit_set.round2b.firstbloom_pilot_v1';
INSERT INTO audit.retrieval_evaluation (retrieval_evaluation_key, retrieval_audit_set_id, model_run_id, audit_split_code, evaluated_at, evaluation_configuration, configuration_sha256, notes) SELECT seed.evaluation_key, audit_set.retrieval_audit_set_id, run.model_run_id, seed.split_code, seed.evaluated_at, seed.configuration, seed.configuration_sha256, 'Language-retrieval evaluation; not coffee flavor accuracy.' FROM _r2b_eval_evaluation_seed AS seed JOIN audit.retrieval_audit_set AS audit_set ON audit_set.retrieval_audit_set_key = 'audit_set.round2b.firstbloom_pilot_v1' JOIN ml.model_run AS run ON run.model_run_key = seed.model_run_key ORDER BY seed.baseline_code, seed.split_code;
INSERT INTO audit.retrieval_metric_value (retrieval_metric_value_key, retrieval_evaluation_id, retrieval_metric_code, cutoff_k, numerator, denominator, metric_value, value_semantics) SELECT metric_seed.metric_value_key, evaluation.retrieval_evaluation_id, calculated.retrieval_metric_code, calculated.cutoff_k, calculated.numerator, calculated.denominator, calculated.metric_value, calculated.value_semantics FROM _r2b_eval_metric_seed AS metric_seed JOIN _r2b_eval_evaluation_seed AS evaluation_seed ON evaluation_seed.evaluation_key = metric_seed.evaluation_key JOIN audit.retrieval_evaluation AS evaluation ON evaluation.retrieval_evaluation_key = evaluation_seed.evaluation_key CROSS JOIN LATERAL audit.calculate_retrieval_metrics('audit_set.round2b.firstbloom_pilot_v1', evaluation_seed.model_run_key, evaluation_seed.split_code) AS calculated WHERE calculated.retrieval_metric_code = metric_seed.metric_code AND calculated.cutoff_k = metric_seed.cutoff_k ORDER BY evaluation.retrieval_evaluation_id, calculated.retrieval_metric_code, calculated.cutoff_k;

DO $final_closure$
DECLARE checked_count BIGINT;
BEGIN
  SELECT count(*) INTO checked_count FROM audit.retrieval_audit_case AS c JOIN audit.retrieval_audit_set AS s ON s.retrieval_audit_set_id = c.retrieval_audit_set_id WHERE s.retrieval_audit_set_key = 'audit_set.round2b.firstbloom_pilot_v1'; IF checked_count <> 300 THEN RAISE EXCEPTION 'Audit case persistence count mismatch'; END IF;
  SELECT count(*) INTO checked_count FROM audit.retrieval_evaluation AS e JOIN audit.retrieval_audit_set AS s ON s.retrieval_audit_set_id = e.retrieval_audit_set_id WHERE s.retrieval_audit_set_key = 'audit_set.round2b.firstbloom_pilot_v1'; IF checked_count <> 8 THEN RAISE EXCEPTION 'Evaluation persistence count mismatch'; END IF;
  SELECT count(*) INTO checked_count FROM audit.retrieval_metric_value AS m JOIN audit.retrieval_evaluation AS e ON e.retrieval_evaluation_id = m.retrieval_evaluation_id JOIN audit.retrieval_audit_set AS s ON s.retrieval_audit_set_id = e.retrieval_audit_set_id WHERE s.retrieval_audit_set_key = 'audit_set.round2b.firstbloom_pilot_v1'; IF checked_count <> 80 THEN RAISE EXCEPTION 'Metric persistence count mismatch'; END IF;
END;
$final_closure$;

COMMIT;
